import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

function isValidDate(dateString) {
  const match = /^\d{4}-\d{2}-\d{2}$/.test(dateString);
  if (!match) return false;
  const date = new Date(dateString + 'T00:00:00Z');
  const [year, month, day] = dateString.split('-').map(Number);
  return date.getUTCFullYear() === year && date.getUTCMonth() + 1 === month && date.getUTCDate() === day;
}

function isPositiveInteger(value) {
  return Number.isInteger(value) && value > 0;
}

function isValidDiscount(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (!isPositiveInteger(line.qty)) return fail('QTY_INVALID');

    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (line.discountPercent !== undefined) {
      newLine.discountPercent = line.discountPercent;
    }
    invoiceLines.push(newLine);
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total amount for a line (qty × unitPrice in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a line (lineTotal × discountPercent / 100).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  if (!line.discountPercent) return 0;
  const discount = roundCents(lineTotal(line) * line.discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const total = Math.max(0, subtotal - discount);
  return { subtotal, discount, total };
}

/**
 * Add a line to an invoice, or increase qty if the SKU already exists.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!isPositiveInteger(qty)) return fail('QTY_INVALID');

  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }
    newLines.push(newLine);
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue an invoice (change status to 'issued' and assign a number).
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    number,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

