  createInvoice(input);
  assert.deepEqual(input, inputCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal works with different quantities', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 8500 }), 850000);
});

test('lineTotal works with different unit prices', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 1000 }), 5000);
  assert.equal(lineTotal({ qty: 5, unitPrice: 100 }), 500);
  assert.equal(lineTotal({ qty: 5, unitPrice: 1 }), 5);
});

test('invoiceTotals sums line totals for subtotal', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.subtotal, 5 * 8500 + 10 * 9500);
  assert.equal(totals.subtotal, 137500);
});

test('invoiceTotals returns total equal to subtotal when no discount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals handles single line', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 25500);
});

test('invoiceTotals handles multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'SUPPORT-HOUR', qty: 1 },
    ],
  });
  const totals = invoiceTotals(invoice.value);
  const expected = 2 * 8500 + 3 * 9500 + 1 * 7250;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, expected);
});

test('addLine adds a new line to the invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
