  const desTotal = 5 * 8500;
  const desDiscount = desTotal * 10 / 100;
  const devTotal = 3 * 9500;
  assert.equal(totals.subtotal, desTotal + devTotal);
  assert.equal(totals.discount, desDiscount);
  assert.equal(totals.total, desTotal - desDiscount + devTotal);
});

