test('invoiceTotals calculates total including discount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const totals = invoiceTotals(invoice.value);
  const desTotal = 5 * 8500;
  const desDiscount = desTotal * 10 / 100;
  const devTotal = 3 * 9500;
  assert.equal(totals.subtotal, desTotal + devTotal);
  assert.equal(totals.discount, desDiscount);
  assert.equal(totals.total, desTotal - desDiscount + devTotal);
});

test('invoiceTotals clamps total at 0', () => {
  const invoice = createInvoice({
